import Std.Array.{Array}
fn fill(a: Array[Int], n: Int) -> Array[Int] {
  if n == 100 { a } else { fill(Array.set(a, 0, n), n + 1) }
}
fn bump(a: Array[Int]) -> Array[Int] { Array.set(a, 0, 9) }
pub fn main() -> Int {
  a = Array.from_list([1, 2, 3])
  b = bump(a)
  c = fill(Array.from_list([0, 0]), 0)
  if Array.to_list(a) == [1, 2, 3] && Array.to_list(b) == [9, 2, 3]
    && Array.get(c, 0) == Some(99) { 0 } else { 1 }
}
